(function () {
  "use strict";
  const core = window.AgendaCore;
  const byId = id => document.getElementById(id);
  const form = byId("agenda-form");
  const list = byId("topic-list");
  const exportButton = byId("export-plan");
  let currentResult = null;
  let classification = "SYNTHETIC";
  let nextId = 1;

  function element(tag, content, className) {
    const node = document.createElement(tag);
    if (content !== undefined) node.textContent = content;
    if (className) node.className = className;
    return node;
  }

  function clearError() {
    byId("error-summary").hidden = true;
    byId("error-summary").textContent = "";
  }

  function showError(error) {
    const box = byId("error-summary");
    box.textContent = error.message || "The agenda could not be read.";
    box.hidden = false;
    box.focus();
  }

  function invalidate() {
    currentResult = null;
    exportButton.disabled = true;
    byId("result-status").textContent = "Inputs changed. Build again before exporting.";
    byId("result-status").className = "";
    byId("result").replaceChildren();
    clearError();
  }

  function addTopic(topic) {
    const row = element("li", undefined, "topic-editor");
    row.dataset.id = topic.id;
    const fields = element("div", undefined, "topic-fields");
    const labelBox = element("div");
    const label = element("label", "Topic label");
    const labelInput = element("input");
    labelInput.type = "text";
    labelInput.maxLength = 120;
    labelInput.required = true;
    labelInput.value = topic.label;
    labelInput.dataset.field = "label";
    labelInput.id = `label-${topic.id}`;
    label.htmlFor = labelInput.id;
    labelBox.append(label, labelInput);
    const minuteBox = element("div");
    const minuteLabel = element("label", "Minutes");
    const minutes = element("input");
    minutes.type = "number";
    minutes.min = "1";
    minutes.max = "120";
    minutes.step = "1";
    minutes.required = true;
    minutes.value = String(topic.minutes);
    minutes.dataset.field = "minutes";
    minutes.id = `minutes-${topic.id}`;
    minuteLabel.htmlFor = minutes.id;
    minuteBox.append(minuteLabel, minutes);
    fields.append(labelBox, minuteBox);
    const controls = element("div", undefined, "topic-controls");
    const requiredLabel = element("label");
    const required = element("input");
    required.type = "checkbox";
    required.checked = topic.required;
    required.dataset.field = "required";
    requiredLabel.append(required, document.createTextNode(" Required topic"));
    const remove = element("button", "Remove topic", "secondary remove");
    remove.type = "button";
    remove.addEventListener("click", () => {
      row.remove();
      invalidate();
      byId("add-topic").focus();
    });
    controls.append(requiredLabel, remove);
    row.append(fields, controls);
    list.append(row);
  }

  function readInput() {
    return {
      classification,
      title: byId("agenda-title").value,
      start: byId("start").value,
      duration_minutes: Number(byId("duration").value),
      wrap_minutes: Number(byId("wrap").value),
      topics: Array.from(list.querySelectorAll(".topic-editor"), row => ({
        id: row.dataset.id,
        label: row.querySelector('[data-field="label"]').value,
        minutes: Number(row.querySelector('[data-field="minutes"]').value),
        required: row.querySelector('[data-field="required"]').checked
      }))
    };
  }

  function populate(input) {
    const checked = core.validate(input);
    classification = checked.classification;
    byId("classification").textContent = `Input classification: ${classification}. Imported text is never evaluated as markup.`;
    byId("agenda-title").value = checked.title;
    byId("start").value = checked.start;
    byId("duration").value = String(checked.duration_minutes);
    byId("wrap").value = String(checked.wrap_minutes);
    list.replaceChildren();
    checked.topics.forEach(addTopic);
    invalidate();
  }

  function render(result) {
    const area = byId("result");
    const status = byId("result-status");
    area.replaceChildren();
    status.className = result.status;
    status.textContent = result.status === "blocked"
      ? `Blocked: required topics exceed available topic time by ${result.required_overrun_minutes} minute(s). Nothing is scheduled.`
      : `Ready to review: ${result.scheduled_minutes} topic minutes within a ${result.session_minutes}-minute session. This is a plan, not an outcome.`;
    area.append(element("p", `Required: ${result.required_minutes} minutes.`, "metric"));
    if (result.status === "ready") {
      area.append(element("p", `Slack before wrap/end: ${result.slack_minutes} minutes.`, "metric"));
      const wrapper = element("div", undefined, "table-wrap");
      const table = element("table");
      table.append(element("caption", `${result.title} · ${result.start}–${result.end}`));
      const head = element("thead");
      const headRow = element("tr");
      ["Topic", "Start", "End", "Minutes", "Kind"].forEach(value => {
        const cell = element("th", value);
        cell.scope = "col";
        headRow.append(cell);
      });
      head.append(headRow);
      const body = element("tbody");
      const rows = result.scheduled.map(topic => [topic.label, topic.start, topic.end, topic.minutes, topic.required ? "Required" : "Optional"]);
      if (result.wrap) rows.push(["Reserved wrap", result.wrap.start, result.wrap.end, result.wrap.minutes, "Wrap"]);
      rows.forEach(values => {
        const row = element("tr");
        values.forEach(value => row.append(element("td", String(value))));
        body.append(row);
      });
      table.append(head, body);
      wrapper.append(table);
      area.append(wrapper);
    }
    area.append(element("h3", "Not scheduled"));
    if (!result.parked.length) area.append(element("p", "Every topic fits."));
    else {
      const parked = element("ul", undefined, "parked-list");
      result.parked.forEach(topic => parked.append(element("li", `${topic.label} (${topic.minutes} min; ${topic.required ? "required" : "optional"}). ${topic.reason}`)));
      area.append(parked);
    }
    currentResult = result;
    exportButton.disabled = false;
  }

  form.addEventListener("input", invalidate);
  form.addEventListener("change", invalidate);
  form.addEventListener("submit", event => {
    event.preventDefault();
    invalidate();
    try {
      render(core.planAgenda(readInput()));
    } catch (error) {
      showError(error);
    }
  });
  byId("load-sample").addEventListener("click", () => {
    populate(core.sample);
    render(core.planAgenda(readInput()));
  });
  byId("add-topic").addEventListener("click", () => {
    if (list.children.length >= 50) {
      showError(new Error("The reference supports at most 50 topics."));
      return;
    }
    const existing = new Set(Array.from(list.children, row => row.dataset.id));
    while (existing.has(`topic-${nextId}`)) nextId += 1;
    addTopic({ id: `topic-${nextId++}`, label: "New topic", minutes: 5, required: false });
    invalidate();
    list.lastElementChild.querySelector("input").focus();
  });
  byId("import-file").addEventListener("change", async event => {
    const file = event.target.files[0];
    if (!file) return;
    try {
      if (file.size > 65_536) throw new Error("Import is limited to 64 KiB.");
      const input = JSON.parse(await file.text());
      const result = core.planAgenda(input);
      populate(input);
      render(result);
    } catch (error) {
      showError(error);
    } finally {
      event.target.value = "";
    }
  });
  exportButton.addEventListener("click", () => {
    if (!currentResult) return;
    const blob = new Blob([JSON.stringify(currentResult, null, 2) + "\n"], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const link = element("a");
    link.href = url;
    link.download = "agenda-pocket-plan.json";
    document.body.append(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  });
  populate(core.sample);
  render(core.planAgenda(readInput()));
})();

(function (root, factory) {
  "use strict";
  const api = factory();
  if (typeof module === "object" && module.exports) module.exports = api;
  else root.AgendaCore = api;
})(typeof globalThis !== "undefined" ? globalThis : this, function () {
  "use strict";

  const sample = {
    classification: "SYNTHETIC",
    title: "Library kit planning reference",
    start: "09:00",
    duration_minutes: 60,
    wrap_minutes: 5,
    topics: [
      { id: "welcome", label: "Confirm the decision to make", minutes: 5, required: true },
      { id: "stock-review", label: "Review fictional kit stock", minutes: 10, required: false },
      { id: "decision", label: "Choose the sample kit scope", minutes: 20, required: true },
      { id: "template-demo", label: "Optional template demonstration", minutes: 15, required: false },
      { id: "risk-check", label: "Check assumptions and open questions", minutes: 10, required: true },
      { id: "roundup", label: "Collect optional follow-up ideas", minutes: 8, required: false }
    ]
  };

  function whole(value, low, high, label) {
    if (!Number.isInteger(value) || value < low || value > high) {
      throw new Error(`${label} must be a whole number from ${low} to ${high}.`);
    }
    return value;
  }

  function text(value, label, limit) {
    if (typeof value !== "string" || !value.trim() || value.length > limit) {
      throw new Error(`${label} must be nonempty text of at most ${limit} characters.`);
    }
    return value.trim();
  }

  function validate(input) {
    if (!input || typeof input !== "object" || Array.isArray(input)) throw new Error("An agenda must be a JSON object.");
    const title = text(input.title, "Title", 120);
    if (typeof input.start !== "string" || !/^([01][0-9]|2[0-3]):[0-5][0-9]$/.test(input.start)) {
      throw new Error("Start must be a same-day HH:MM time.");
    }
    const duration = whole(input.duration_minutes, 1, 480, "Session minutes");
    const wrap = whole(input.wrap_minutes, 0, duration, "Wrap minutes");
    const startMinutes = Number(input.start.slice(0, 2)) * 60 + Number(input.start.slice(3));
    if (startMinutes + duration > 1440) throw new Error("The session must end no later than midnight.");
    if (!Array.isArray(input.topics) || input.topics.length < 1 || input.topics.length > 50) {
      throw new Error("Supply 1 to 50 topics.");
    }
    const seen = new Set();
    const topics = input.topics.map((topic, index) => {
      if (!topic || typeof topic !== "object" || Array.isArray(topic)) throw new Error(`Topic ${index + 1} must be an object.`);
      if (typeof topic.id !== "string" || topic.id.length > 40 || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(topic.id)) {
        throw new Error(`Topic ${index + 1} needs a lowercase-hyphenated ID of at most 40 characters.`);
      }
      if (seen.has(topic.id)) throw new Error(`Duplicate topic ID: ${topic.id}.`);
      seen.add(topic.id);
      if (typeof topic.required !== "boolean") throw new Error(`Topic ${index + 1} required must be true or false.`);
      return {
        id: topic.id, label: text(topic.label, `Topic ${index + 1} label`, 120),
        minutes: whole(topic.minutes, 1, 120, `Topic ${index + 1} minutes`),
        required: topic.required
      };
    });
    return {
      classification: input.classification === undefined ? "LOCAL-INPUT" : text(input.classification, "Classification", 80),
      title, start: input.start, startMinutes, duration_minutes: duration, wrap_minutes: wrap, topics
    };
  }

  function clock(minutes) {
    return `${String(Math.floor(minutes / 60)).padStart(2, "0")}:${String(minutes % 60).padStart(2, "0")}`;
  }

  function planAgenda(input) {
    const agenda = validate(input);
    const budget = agenda.duration_minutes - agenda.wrap_minutes;
    const requiredMinutes = agenda.topics.filter(topic => topic.required).reduce((sum, topic) => sum + topic.minutes, 0);
    const result = {
      classification: agenda.classification,
      artifact_kind: "offline-reference-plan-not-a-meeting-outcome",
      title: agenda.title,
      status: requiredMinutes > budget ? "blocked" : "ready",
      start: agenda.start,
      end: clock(agenda.startMinutes + agenda.duration_minutes),
      session_minutes: agenda.duration_minutes,
      required_minutes: requiredMinutes,
      required_overrun_minutes: Math.max(0, requiredMinutes - budget),
      scheduled_minutes: 0,
      slack_minutes: null,
      scheduled: [],
      parked: [],
      wrap: null
    };
    if (result.status === "blocked") {
      result.parked = agenda.topics.map(topic => ({ ...topic, reason: "Session blocked until all required topics fit." }));
      return result;
    }
    let used = 0;
    let remainingRequired = requiredMinutes;
    for (const topic of agenda.topics) {
      if (topic.required || used + topic.minutes + remainingRequired <= budget) {
        const start = agenda.startMinutes + used;
        result.scheduled.push({ ...topic, start: clock(start), end: clock(start + topic.minutes) });
        used += topic.minutes;
        if (topic.required) remainingRequired -= topic.minutes;
      } else {
        result.parked.push({ ...topic, reason: "Optional topic does not fit after reserving required time and wrap." });
      }
    }
    result.scheduled_minutes = used;
    result.slack_minutes = budget - used;
    if (agenda.wrap_minutes > 0) {
      result.wrap = {
        start: clock(agenda.startMinutes + budget),
        end: result.end,
        minutes: agenda.wrap_minutes
      };
    }
    return result;
  }

  return Object.freeze({ sample, validate, planAgenda });
});

:root {
  color-scheme: light;
  --ink: #172b2b;
  --muted: #405858;
  --paper: #f5f7f2;
  --line: #bac9c4;
  --accent: #075e55;
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--paper); color: var(--ink); font: 1rem/1.55 system-ui, sans-serif; }
.hero, .layout, footer { width: min(1180px, 100% - 2rem); margin-inline: auto; }
.hero { padding-block: 2.5rem 1.5rem; max-width: 1180px; }
.eyebrow { letter-spacing: .09em; text-transform: uppercase; font-size: .8rem; font-weight: 750; }
h1 { font-size: clamp(2rem, 5vw, 3.5rem); line-height: 1.1; max-width: 22ch; margin-block: .6rem 1rem; }
h2 { margin-top: 0; font-size: 1.35rem; }
h3 { font-size: 1.05rem; }
.hero > p { max-width: 78ch; }
.boundary, .small { color: var(--muted); font-size: .9rem; }
.layout { display: grid; grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr); gap: 1.2rem; align-items: start; }
.panel { background: white; border: 1px solid var(--line); border-radius: .8rem; padding: 1.3rem; min-width: 0; }
label { display: block; font-weight: 650; margin-bottom: .25rem; }
input, button { font: inherit; }
input[type="text"], input[type="number"], input[type="time"] { width: 100%; min-height: 2.7rem; padding: .5rem; border: 1px solid #647b73; border-radius: .3rem; background: white; color: var(--ink); }
input[type="checkbox"] { width: 1.1rem; height: 1.1rem; vertical-align: middle; accent-color: var(--accent); }
input[type="file"] { max-width: 100%; font-size: .85rem; }
button { padding: .65rem .9rem; border-radius: .4rem; border: 2px solid var(--accent); background: var(--accent); color: white; font-weight: 700; cursor: pointer; }
button.secondary { background: white; color: var(--accent); }
button:disabled { opacity: .55; cursor: not-allowed; }
button.remove { font-size: .8rem; padding: .35rem .5rem; }
:focus-visible { outline: 3px solid #8a3b00; outline-offset: 3px; }
.toolbar { display: flex; gap: .7rem; flex-wrap: wrap; align-items: center; margin-block: 1rem; }
.import-label { font-size: .85rem; max-width: 100%; }
.time-fields { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: .7rem; margin: 1.2rem 0; padding: .8rem; border: 1px solid var(--line); border-radius: .3rem; }
legend { font-size: .9rem; font-weight: 700; padding-inline: .25rem; }
ol { margin: 0; padding-left: 1.3rem; }
.topic-editor { padding: .7rem 0; border-top: 1px solid var(--line); }
.topic-fields { display: grid; grid-template-columns: minmax(0, 1fr) 6rem; gap: .65rem; align-items: end; }
.topic-controls { display: flex; justify-content: space-between; gap: .5rem; align-items: center; margin-top: .6rem; }
.topic-controls label { font-size: .9rem; margin: 0; }
.error { background: #fff3e4; border-left: 4px solid #864400; padding: .9rem; margin-block: 1rem; }
.blocked { border-left: 4px solid #864400; padding-left: .8rem; font-weight: 700; }
.ready { border-left: 4px solid var(--accent); padding-left: .8rem; font-weight: 700; }
.metric { margin-block: .35rem; }
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: .88rem; margin-block: 1rem; }
caption { text-align: left; font-weight: 700; margin-bottom: .4rem; }
th, td { padding: .5rem .35rem; border-bottom: 1px solid var(--line); text-align: left; vertical-align: top; overflow-wrap: anywhere; }
th { background: #edf3f0; }
.parked-list { padding-left: 1.2rem; }
.parked-list li { margin-block: .45rem; }
footer { padding-block: 2rem; color: var(--muted); font-size: .9rem; }
.skip-link { position: absolute; left: 1rem; top: -5rem; padding: .5rem; background: white; color: var(--accent); z-index: 2; }
.skip-link:focus { top: .5rem; }
[hidden] { display: none !important; }
@media (max-width: 850px) { .layout { grid-template-columns: 1fr; } }
@media (max-width: 420px) {
  .panel { padding: .85rem; }
  .time-fields { grid-template-columns: 1fr; }
  .topic-fields { grid-template-columns: 1fr; }
  .topic-controls { align-items: start; flex-wrap: wrap; }
}
@media print {
  .hero { padding-top: 0; }
  .layout { display: block; }
  .layout > section:first-child, button, .skip-link { display: none; }
  .panel { border: none; padding: 0; }
  body { background: white; }
}

"use strict";
const test = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const vm = require("node:vm");
const root = path.resolve(__dirname, "..");
const sample = JSON.parse(fs.readFileSync(path.join(root, "data/sample-agenda.json"), "utf8"));
const cases = JSON.parse(fs.readFileSync(path.join(root, "data/acceptance-cases.json"), "utf8")).cases;
const clone = value => JSON.parse(JSON.stringify(value));
// Exercise the browser script independently of any enclosing package's module type.
const browser = {};
vm.runInNewContext(fs.readFileSync(path.join(root, "demo/core.js"), "utf8"), browser, { timeout: 1000 });
const core = {
  sample: clone(browser.AgendaCore.sample),
  planAgenda: input => clone(browser.AgendaCore.planAgenda(input))
};

for (const fixture of cases) {
  test(`numerical case: ${fixture.id}`, () => {
    const input = Object.assign(clone(sample), fixture.patch);
    if (fixture.all_required) input.topics.forEach(topic => { topic.required = true; });
    const result = core.planAgenda(input);
    assert.deepEqual({
      status: result.status,
      scheduled_minutes: result.scheduled_minutes,
      slack_minutes: result.slack_minutes,
      required_overrun_minutes: result.required_overrun_minutes,
      scheduled_ids: result.scheduled.map(topic => topic.id),
      parked_ids: result.parked.map(topic => topic.id),
      wrap_start: result.wrap ? result.wrap.start : null
    }, fixture.expected);
    if (result.status === "ready") {
      assert.equal(result.scheduled_minutes + result.slack_minutes + input.wrap_minutes, input.duration_minutes);
      assert.deepEqual(result.scheduled.filter(topic => topic.required).map(topic => topic.id), input.topics.filter(topic => topic.required).map(topic => topic.id));
    }
  });
}

test("embedded offline sample equals structured source", () => assert.deepEqual(core.sample, sample));
test("planning is deterministic and does not mutate inputs", () => {
  const input = clone(sample);
  const before = JSON.stringify(input);
  assert.deepEqual(core.planAgenda(input), core.planAgenda(input));
  assert.equal(JSON.stringify(input), before);
});
test("reject duplicate IDs", () => {
  const input = clone(sample);
  input.topics[1].id = input.topics[0].id;
  assert.throws(() => core.planAgenda(input), /Duplicate topic ID/);
});
test("reject invalid minute and boolean types", () => {
  for (const value of [0, -1, 1.5, "5", null, Infinity]) {
    const input = clone(sample);
    input.topics[0].minutes = value;
    assert.throws(() => core.planAgenda(input), /whole number/);
  }
  const input = clone(sample);
  input.topics[0].required = "true";
  assert.throws(() => core.planAgenda(input), /true or false/);
});
test("validate top-level objects and topic bounds", () => {
  for (const value of [null, [], "agenda", {}]) assert.throws(() => core.planAgenda(value));
  const input = clone(sample);
  input.topics = [];
  assert.throws(() => core.planAgenda(input), /1 to 50/);
  input.topics = Array.from({ length: 51 }, (_, index) => ({ id: `topic-${index}`, label: "SYNTHETIC", minutes: 1, required: false }));
  assert.throws(() => core.planAgenda(input), /1 to 50/);
});
test("reject crossing midnight and malformed clock", () => {
  assert.throws(() => core.planAgenda({ ...clone(sample), start: "23:01" }), /midnight/);
  for (const start of ["24:00", "9:00", "09:60", "not-time"]) {
    assert.throws(() => core.planAgenda({ ...clone(sample), start }), /HH:MM/);
  }
  assert.equal(core.planAgenda({ ...clone(sample), start: "23:00" }).end, "24:00");
});
test("optional-only agenda may reserve the whole session for wrap", () => {
  const input = clone(sample);
  input.topics.forEach(topic => { topic.required = false; });
  input.wrap_minutes = input.duration_minutes;
  const result = core.planAgenda(input);
  assert.equal(result.status, "ready");
  assert.equal(result.scheduled.length, 0);
  assert.equal(result.wrap.minutes, 60);
});
test("literal angle-bracket text is kept as text in the core", () => {
  const input = clone(sample);
  input.topics[0].label = "<b>SYNTHETIC label</b>";
